using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person → ElementType: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

Person roundTripped = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {roundTripped}");

// 2) Probe without throwing: TryGetTypeInfo() returns false when the type isn't resolvable.
//    Remove the resolver so nothing can be resolved.
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = null   // no resolver → nothing is resolvable
};

if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"Found metadata: {info!.Type.Name}");
else
    Console.WriteLine("No metadata for Person (resolver is null) — no exception thrown.");

// Also show the positive path for TryGetTypeInfo.
if (options.TryGetTypeInfo(typeof(Person), out info))
    Console.WriteLine($"TryGetTypeInfo succeeded: {info!.Type.Name}");

record Person(string Name, int Age);

